 try{const s=JSON.parse(localStorage.getItem(saveKey));if(s?.version===1){me.area=['hub',...C.DISTRICTS.map(d=>d.id)].includes(s.area)?s.area:'hub';me.plot=C.restorePlot(s.plot);if(catalog.has(s.avatar))me.avatar=s.avatar;me.name=String(s.name||'Guest').slice(0,22);if(s.style&&[['skin',5],['hair',3],['pants',3]].every(([k,max])=>Number.isInteger(s.style[k])&&s.style[k]>=0&&s.style[k]<=max))me.style={skin:s.style.skin,hair:s.style.hair,pants:s.style.pants,print:Number.isInteger(s.style.print)&&s.style.print>=0&&s.style.print<=2?s.style.print:0};if(Number.isFinite(s.x)&&Number.isFinite(s.y)&&!C.blocked(s.x,s.y,me)){me.x=s.x;me.y=s.y;}for(const k of ['xp','credits','kills','jobs','deaths'])if(Number.isSafeInteger(s[k])&&s[k]>=0&&s[k]<1000000)me[k]=s[k];const seen=new Set();if(Array.isArray(s.inventory))me.inventory=s.inventory.filter(i=>i&&ITEMS.some(t=>t.id===i.item)&&typeof i.uid==='string'&&/^gear-\d+$/.test(i.uid)&&!seen.has(i.uid)&&seen.add(i.uid)).slice(0,100);me.equipped={};for(const item of me.inventory){const t=ITEMS.find(t=>t.id===item.item);if(s.equipped?.[t.slot]===item.uid)me.equipped[t.slot]=item.uid;}engine.serial=Math.max(0,...me.inventory.map(i=>Number(i.uid.slice(5))));me.route=Number.isInteger(s.route)?Math.max(0,Math.min(3,s.route)):0;me.completed=me.route===3;paintX=me.x;paintY=me.y;if(C.blocked(me.x,me.y,me)){me.x=1120;me.y=me.area==='hub'?900:1280;paintX=me.x;paintY=me.y;}state=engine.snapshot('solo');}}catch{/* New game if local storage is malformed or unavailable. */}
