 function frame(time){const dt=Math.min(1,(time-lastFrame)/1000||.016);lastFrame=time;if(!online){const m=movement();engine.input('solo',m.x,m.y);engine.trigger('solo',entered&&!activePanel&&!document.hidden&&(firing||keys.has(' ')),aim.x,aim.y);if(entered&&!activePanel&&!document.hidden)for(let remaining=dt;remaining>0;remaining-=.05)engine.tick(Math.min(.05,remaining));refreshState();}draw(time,dt);if(time-lastDrawUI>150){updateUI();lastDrawUI=time;}if(time-saveAt>2500){save();saveAt=time;}requestAnimationFrame(frame);}
 async function request(path,body){const response=await fetch(api+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:`Bearer ${session}`}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Room request failed.');return result;}
 async function connect(){const net=window.MEME_CITY_NETWORK;if(!net?.enabled||new URLSearchParams(location.search).get('solo')==='1')return;try{const u=new URL(net.apiBase||'api/city',location.href);if(u.protocol!=='https:'&&!['localhost','127.0.0.1','terminal.local'].includes(u.hostname))throw Error('Room hosting requires HTTPS.');api=u.href.replace(/\/$/,'');const r=await request('/join',{name:me.name,avatar:me.avatar});session=r.session;state=r.state;me=state.self;online=true;$('#room-mode').textContent='ONLINE / SHARED ROOM';$('#save-state').textContent='Online room progress is temporary and separate from your solo save.';toast('Joined the multiplayer room. Other players can now meet you here.');stream=new AbortController();readStream(stream.signal);inputTimer=setInterval(async()=>{if(onlineInputBusy)return;onlineInputBusy=true;try{const m=movement();await request('/input',{...m,fire:!activePanel&&!document.hidden&&(firing||keys.has(' ')),aimX:aim.x,aimY:aim.y});}catch{disconnect();}finally{onlineInputBusy=false;}},100);}catch(e){toast(`${e.message} Playing solo.`);}}
 async function readStream(signal){try{const response=await fetch(api+'/events',{headers:{Authorization:`Bearer ${session}`},signal,cache:'no-store'});if(!response.ok)throw Error('Room stream failed.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(online){const {value,done}=await reader.read();if(done)throw Error('Room disconnected.');buffer+=decoder.decode(value,{stream:true});let index;while((index=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,index).trim();buffer=buffer.slice(index+1);if(line){state=JSON.parse(line);me=state.self;if(activePanel==='chat'){const log=$('.chat-log');if(log){log.replaceChildren(...state.chat.map(m=>node('p','',`${m.name}: ${m.text}`)));}}}}}}catch(e){if(e.name!=='AbortError')disconnect();}}
 function disconnect(){if(!online)return;online=false;stream?.abort();clearInterval(inputTimer);me=engine.player('solo');refreshState();$('#room-mode').textContent='SOLO / ROOM DISCONNECTED';$('#save-state').textContent='Returned to your separate solo save.';if(activePanel)closePanel();toast('Room connection lost. Returned to your solo character.');}
