 window.addEventListener('keydown',e=>{if(activePanel||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if(k==='escape'&&!activePanel&&entered){e.preventDefault();panel('pause');return;}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e',' ','shift'].includes(k)){e.preventDefault();if(!entered)return;keys.add(k);if(k==='e'&&!e.repeat)interact();if(k===' '&&!e.repeat)fire();if(k==='shift'&&!e.repeat)action({type:'dash'},true);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();held.clear();stick={x:0,y:0};firing=false;});document.addEventListener('visibilitychange',()=>{keys.clear();held.clear();stick={x:0,y:0};firing=false;save();});window.addEventListener('pagehide',save);updateUI();requestAnimationFrame(frame);
